<?php
declare(strict_types=1);session_start();require_once __DIR__.'/config/purchase_step14.php';if(empty($_SESSION['spp_csrf']))$_SESSION['spp_csrf']=bin2hex(random_bytes(24));$csrf=(string)$_SESSION['spp_csrf'];$error=null;$success=null;$bills=[];$payments=[];$selected=(int)($_GET['bill']??$_POST['purchase_bill_id']??0);
try{$pdo=business_db();purchase_step14_ensure($pdo);$ctx=purchase_step14_context($pdo);$orgId=(int)$ctx['organization_id'];if($_SERVER['REQUEST_METHOD']==='POST'){if(!hash_equals($csrf,(string)($_POST['csrf']??'')))throw new RuntimeException('Security token mismatch.');$action=(string)($_POST['action']??'add');if($action==='add'){$id=purchase_step14_add_payment($pdo,$selected,(string)$_POST['payment_date'],(float)$_POST['amount'],(string)$_POST['payment_method'],(string)($_POST['reference_no']??''),(string)($_POST['notes']??''));$success='Supplier payment #'.$id.' recorded.';}elseif($action==='reverse'){purchase_step14_reverse_payment($pdo,(int)$_POST['payment_id'],(string)($_POST['reason']??''));$success='Supplier payment reversed with audit history.';}}foreach(purchase_step14_bill_rows($pdo,$orgId,'active') as $b){purchase_step14_recalc_bill($pdo,$orgId,(int)$b['id']);}$bills=purchase_step14_bill_rows($pdo,$orgId,'active');$stmt=$pdo->prepare("SELECT p.*,b.invoice_number,s.supplier_name FROM purchase_payments p JOIN purchase_bills b ON b.id=p.purchase_bill_id AND b.organization_id=p.organization_id JOIN purchase_suppliers s ON s.id=p.supplier_id AND s.organization_id=p.organization_id WHERE p.organization_id=? ORDER BY p.payment_date DESC,p.id DESC LIMIT 200");$stmt->execute([$orgId]);$payments=$stmt->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
function spp_h(mixed $v):string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}function spp_m(mixed $v):string{return '₹'.number_format((float)$v,2,'.',',');}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Supplier Payables - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="purchase_center.php"><img src="../img/logo.png" alt="logo"><span><strong>Healthcare Wellness Club</strong><small>STEP 14 • Supplier Payables</small></span></a><div class="os-top-actions"><a class="os-btn" href="purchase_bills.php">Bills</a><a class="os-btn" href="supplier_center.php">Suppliers</a><a class="os-btn primary" href="purchase_center.php">Purchase Center</a></div></div></header><div class="os-layout"><aside class="os-sidebar"><div class="os-nav-label">Purchases</div><nav class="os-nav"><a href="purchase_center.php"><i class="dot"></i>Purchase Center</a><a href="supplier_center.php"><i class="dot"></i>Suppliers</a><a href="purchase_orders.php"><i class="dot"></i>Purchase Orders</a><a href="purchase_bills.php"><i class="dot"></i>Bills / Invoices</a><a href="purchase_receipts.php"><i class="dot"></i>Receipts</a><a class="active" href="supplier_payments.php"><i class="dot"></i>Payables</a><a href="purchase_returns.php"><i class="dot"></i>Returns</a></nav></aside><main class="os-main"><section class="os-hero pp-hero"><div class="os-kicker">STEP 14E • SUPPLIER PAYABLES</div><h1>Track exactly what is owed, paid and still outstanding.</h1><p>Outstanding = Bill Total − Purchase Return Credit − Active Payments. Payment never changes stock and never creates a second purchase expense fact.</p><div class="os-status-row"><span class="os-chip <?= $error===null?'good':'' ?>"><?= $error===null?'PAYABLES LIVE':'Review required' ?></span><span class="os-chip"><?= count($bills) ?> active bills</span><span class="os-chip"><?= count($payments) ?> payment records</span></div></section><?php if($error):?><div class="pp-alert bad"><strong>Payable diagnostic:</strong> <?= spp_h($error) ?></div><?php endif;?><?php if($success):?><div class="pp-alert good"><strong>Saved:</strong> <?= spp_h($success) ?></div><?php endif;?><?php if(!$error):?><section class="pp-grid" style="margin-top:14px"><article class="os-card pp-span-5"><h2>Record Supplier Payment</h2><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= spp_h($csrf) ?>"><input type="hidden" name="action" value="add"><label>Bill<select name="purchase_bill_id" required><option value="">Choose outstanding bill…</option><?php foreach($bills as $b):if((float)$b['outstanding']<=0.009)continue;?><option value="<?= (int)$b['id'] ?>" <?= $selected===(int)$b['id']?'selected':'' ?>><?= spp_h($b['supplier_name'].' • '.$b['invoice_number'].' • Due '.spp_m($b['outstanding'])) ?></option><?php endforeach;?></select></label><label>Payment Date<input type="date" name="payment_date" value="<?= date('Y-m-d') ?>" required></label><label>Amount<input type="number" min="0.01" step="0.01" name="amount" required></label><label>Method<select name="payment_method"><option value="upi">UPI</option><option value="bank">Bank Transfer</option><option value="cash">Cash</option><option value="card">Card</option><option value="cheque">Cheque</option><option value="other">Other</option></select></label><label>Reference No.<input name="reference_no"></label><label>Notes<textarea name="notes" rows="2"></textarea></label><button>Record Payment →</button></form></article><article class="os-card pp-span-7"><h2>Open Payables</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Supplier</th><th>Invoice</th><th>Due</th><th>Total</th><th>Return</th><th>Paid</th><th>Outstanding</th><th>Status</th></tr></thead><tbody><?php foreach($bills as $b):?><tr><td><?= spp_h($b['supplier_name']) ?></td><td><a href="purchase_bills.php?bill=<?= (int)$b['id'] ?>"><b><?= spp_h($b['invoice_number']) ?></b></a></td><td><?= spp_h($b['due_date']?:'—') ?></td><td><?= spp_m($b['total_amount']) ?></td><td><?= spp_m($b['return_credit']) ?></td><td><?= spp_m($b['paid_amount']) ?></td><td><b><?= spp_m($b['outstanding']) ?></b></td><td><span class="pp-badge <?= $b['payment_status']==='credit'?'warn':'' ?>"><?= spp_h(strtoupper($b['payment_status'])) ?></span></td></tr><?php endforeach;?><?php if(!$bills):?><tr><td colspan="8">No active supplier bills.</td></tr><?php endif;?></tbody></table></div></article></section><section class="os-card" style="margin-top:14px"><h2>Payment History</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Date</th><th>Payment</th><th>Supplier</th><th>Invoice</th><th>Amount</th><th>Method</th><th>Status</th><th>Action</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?= spp_h($p['payment_date']) ?></td><td>#<?= (int)$p['id'] ?></td><td><?= spp_h($p['supplier_name']) ?></td><td><?= spp_h($p['invoice_number']) ?></td><td><?= spp_m($p['amount']) ?></td><td><?= spp_h(strtoupper($p['payment_method'])) ?><small><?= spp_h($p['reference_no']?:'') ?></small></td><td><span class="pp-badge <?= $p['status']==='active'?'':'warn' ?>"><?= spp_h(strtoupper($p['status'])) ?></span></td><td><?php if($p['status']==='active'):?><details><summary>Reverse</summary><form method="post" class="pp-form"><input type="hidden" name="csrf" value="<?= spp_h($csrf) ?>"><input type="hidden" name="action" value="reverse"><input type="hidden" name="payment_id" value="<?= (int)$p['id'] ?>"><input type="hidden" name="purchase_bill_id" value="<?= (int)$p['purchase_bill_id'] ?>"><input name="reason" minlength="5" placeholder="Reason" required><button>Confirm</button></form></details><?php else:?>—<?php endif;?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="8">No supplier payments yet.</td></tr><?php endif;?></tbody></table></div></section><?php endif;?><div class="os-footer-note"><strong>Payment rule:</strong> overpayment is blocked against current outstanding. Reversed payments remain visible and auditable.</div></main></div><script src="assets/business-collapsible.js?v=20260820-1" defer></script></body></html>
